const $=s=>document.querySelector(s),grid=$('#custom-grid'),built=$('#built-grid'),summary=$('#grid-summary'),help=$('#grid-help'),status=$('#build-status');let mode='spaces',running=false,attempts=0,pattern,highlights=new Set();
const shuffle=a=>{a=[...a];for(let i=a.length-1;i;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a},box=(r,c)=>Math.floor(r/3)*3+Math.floor(c/3),key=(r,c)=>r*9+c;
function freshPattern(){const p=Array.from({length:9},()=>Array(9).fill(false));for(let band=0;band<3;band++){const o=[shuffle([0,1,2]),shuffle([0,1,2]),shuffle([0,1,2])],rows=shuffle([0,1,2]),perms=shuffle([[0,1,2],[1,2,0],[2,0,1]]);for(let local=0;local<3;local++)for(let st=0;st<3;st++)p[band*3+local][st*3+o[st][perms[rows[local]][st]]]=true}return p}
function validPattern(){return pattern.every(r=>r.filter(Boolean).length===3)&&[0,1,2,3,4,5,6,7,8].every(c=>pattern.map(r=>r[c]).filter(Boolean).length===3)&&[0,1,2].every(br=>[0,1,2].every(bc=>pattern.slice(br*3,br*3+3).flatMap(r=>r.slice(bc*3,bc*3+3)).filter(Boolean).length===3))}
function counts(r,c){return[pattern[r].filter(Boolean).length,pattern.map(x=>x[c]).filter(Boolean).length,pattern.slice(Math.floor(r/3)*3,Math.floor(r/3)*3+3).flatMap(x=>x.slice(Math.floor(c/3)*3,Math.floor(c/3)*3+3)).filter(Boolean).length]}
function render(){grid.replaceChildren();let spaces=0;for(let r=0;r<9;r++)for(let c=0;c<9;c++){let shaded=pattern[r][c],cell=document.createElement('button');if(shaded)spaces++;cell.type='button';cell.className=`cell custom-cell${shaded?' shaded':''}${highlights.has(key(r,c))?' highlighted':''}${c%3===2?' box-right':''}${r%3===2?' box-bottom':''}`;cell.setAttribute('aria-label',`Row ${r+1}, column ${c+1}`);cell.onclick=()=>click(r,c);grid.append(cell)}summary.textContent=`${spaces} spaces · ${highlights.size} clues`;$('#build-now').disabled=!validPattern()||!highlights.size;}
function click(r,c){if(mode==='spaces'){if(pattern[r][c]){pattern[r][c]=false;highlights.delete(key(r,c))}else if(counts(r,c).every(n=>n<3))pattern[r][c]=true;else{status.textContent='That space would make a row, column, or box exceed three grey cells.';return}}else if(!pattern[r][c]){let k=key(r,c);highlights.has(k)?highlights.delete(k):highlights.add(k)}render()}
function options(mask){return shuffle([1,2,3,4,5,6].filter(d=>!(mask&(1<<d))));}
function solve(givens,limit=1){const v=givens.map(r=>[...r]),ru=Array(9).fill(0),cu=Array(9).fill(0),bu=Array(9).fill(0),open=[];for(let r=0;r<9;r++)for(let c=0;c<9;c++){if(pattern[r][c])continue;let d=v[r][c],b=box(r,c);if(d){let f=1<<d;if((ru[r]|cu[c]|bu[b])&f)return{count:0,values:null};ru[r]|=f;cu[c]|=f;bu[b]|=f}else open.push({r,c,b})}let count=0,first=null;function search(cells){if(count>=limit)return;if(!cells.length){count++;first??=v.map(r=>[...r]);return}let bi=-1,opts;cells.forEach((x,i)=>{let o=options(ru[x.r]|cu[x.c]|bu[x.b]);if(!opts||o.length<opts.length){bi=i;opts=o}});if(!opts.length)return;let x=cells[bi],next=cells.filter((_,i)=>i!==bi);for(let d of opts){let f=1<<d;v[x.r][x.c]=d;ru[x.r]|=f;cu[x.c]|=f;bu[x.b]|=f;search(next);v[x.r][x.c]=null;ru[x.r]&=~f;cu[x.c]&=~f;bu[x.b]&=~f;if(count>=limit)return}}search(open);return{count,values:first}}
function showResult(values){built.replaceChildren();for(let r=0;r<9;r++)for(let c=0;c<9;c++){let x=document.createElement('div'),d=values[r][c];x.className=`cell${pattern[r][c]?' shaded':''}${!pattern[r][c]&&!d?' empty':''}${c%3===2?' box-right':''}${r%3===2?' box-bottom':''}`;if(d)x.textContent=d;built.append(x)}$('#built-result').hidden=false;$('#attempt-count').textContent=`${attempts} attempts`}
function tryBatch(){if(!running)return;let start=performance.now();do{attempts++;let blank=Array.from({length:9},()=>Array(9).fill(null)),solution=solve(blank).values;if(!solution)continue;let givens=blank;for(let k of highlights){let r=Math.floor(k/9),c=k%9;givens[r][c]=solution[r][c]}let tested=solve(givens,2);if(tested.count===1){running=false;$('#halt-build').disabled=true;$('#build-now').disabled=false;showResult(givens);status.textContent='Unique puzzle found from your selected green clues.';return}}while(running&&performance.now()-start<35);status.textContent=`Trying completed grids… ${attempts} tested.`;requestAnimationFrame(tryBatch)}
$('#space-mode').onclick=()=>{mode='spaces';$('#space-mode').classList.add('active');$('#clue-mode').classList.remove('active');help.textContent='Space mode: click cells to set the 27 grey spaces. A row, column, or box cannot exceed three spaces.'};$('#clue-mode').onclick=()=>{mode='clues';$('#clue-mode').classList.add('active');$('#space-mode').classList.remove('active');help.textContent='Clue mode: click any white cell to highlight it green. These become the givens.'};$('#new-pattern').onclick=()=>{pattern=freshPattern();highlights.clear();render();status.textContent='New valid 27-space pattern created.'};$('#clear-highlights').onclick=()=>{highlights.clear();render()};$('#build-now').onclick=()=>{if(!validPattern()||!highlights.size)return;running=true;attempts=0;$('#halt-build').disabled=false;$('#build-now').disabled=true;$('#built-result').hidden=true;status.textContent='Trying completed grids…';requestAnimationFrame(tryBatch)};$('#halt-build').onclick=()=>{running=false;$('#halt-build').disabled=true;$('#build-now').disabled=false;status.textContent=`Stopped after ${attempts} attempts.`};pattern=freshPattern();render();
